pages=[
('Frá afleiðu að stofnfalli','Finna eitt stofnfall og sannreyna það með diffrun.',r'''<p>Þegar við diffrum þekkjum við fallið og finnum afleiðuna. Nú snúum við spurningunni við: <strong>Hvaða fall hefur afleiðuna \(2x\)?</strong></p><div class="formula">\[F(x)=x^2\quad\Longrightarrow\quad F'(x)=2x.\]</div><p>Við segjum að \(x^2\) sé <strong>stofnfall</strong> fallsins \(2x\).</p><aside>Fall \(F\) er stofnfall falls \(f\) á bili ef \(F'(x)=f(x)\) fyrir öll \(x\) á bilinu.</aside><h3>Leyst dæmi: stofnfall \(6x\)</h3><p>Afleiða \(x^2\) er \(2x\). Þreföldum fallið til að fá þrefalda afleiðu:</p>\[F(x)=3x^2\]\[F'(x)=3\cdot2x=6x.\]<p>Því er \(3x^2\) stofnfall \(6x\). Við athugum bæði veldi og stuðul.</p><h3>Fastaföll og hornaföll</h3><p>Stofnfall \(5\) er \(5x\), því \((5x)'=5\). Stofnfall \(\cos x\) er \(\sin x\). Við notum radíana við hornaföll.</p>''',[
(r'Finndu eitt stofnfall \(4x\).','Hvaða fall gefur x í fyrstu veldi við diffrun?',r'Prófaðu \(Ax^2\). Afleiðan verður \(2Ax\).',r'\(F(x)=2x^2\), því \(F\prime(x)=4x\).'),
(r'Er \(x^4\) stofnfall \(x^3\)?','Sannreyndu með diffrun.',r'\((x^4)\prime=4x^3\). Stuðullinn er of stór.',r'Nei. Eitt rétt stofnfall er \(x^4/4\).'),
(r'Finndu eitt stofnfall \(-\sin x\).','Rifjaðu upp afleiðu cosinus.',r'\((\cos x)\prime=-\sin x\).',r'\(F(x)=\cos x\).')]),
('Hvers vegna þarf fastann C?','Útskýra hvers vegna sama fall á mörg stofnföll.',r'''<p>Skoðum þrjú föll:</p>\[F(x)=x^2\]\[G(x)=x^2+3\]\[H(x)=x^2-5.\]<p>Öll hafa afleiðuna \(2x\). Fastaliður hverfur við diffrun. Því er \(x^2+C\) stofnfall \(2x\) fyrir hvaða fasta \(C\) sem er.</p><aside>Á samfelldu bili eru öll stofnföll sama falls frábrugðin hvert öðru um fasta.</aside><h3>Skoðaðu fjölskyldu stofnfalla</h3><p>Spáðu fyrst: Breytist halli grafsins þegar \(C\) breytist? Færðu síðan rennistikuna.</p><label for="c">Heildunarfasti C: <output id="cv">0</output></label><input id="c" type="range" min="-4" max="4" step="0.5" value="0"><svg id="graph" viewBox="0 0 320 400" role="img" aria-label="Graf fallsins x í öðru veldi plús C; rennistika breytir lóðréttri staðsetningu."></svg><p id="geq" aria-live="polite"></p><p>Grafið færist upp eða niður, en hallinn við sama \(x\)-gildi helst sá sami. Berðu saman gröfin \(x^2\), \(x^2+2\) og \(x^2-2\).</p>''',[
(r'Finndu þrjú stofnföll \(3x^2\).','Byrjaðu á einu stofnfalli og bættu við mismunandi föstum.',r'\((x^3+C)\prime=3x^2\).',r'Til dæmis \(x^3\), \(x^3+2\) og \(x^3-7\).'),
(r'Af hverju er \(x^2+2x\) ekki stofnfall \(2x\)?','Viðbótin þarf að hafa afleiðuna núll.',r'Afleiða \(2x\) er \(2\), ekki núll.',r'Afleiða alls fallsins er \(2x+2\). Viðbótin \(2x\) er ekki fasti.')]),
('Táknmál óákveðins heildis','Lesa og nota táknmál heildunar.',r'''<p>Að finna stofnföll er kallað að <strong>heilda</strong>. Við skrifum:</p><div class="formula">\[\int f(x)\,dx=F(x)+C.\]</div><ul><li>\(\int\) er heildistáknið.</li><li>\(f(x)\) er heildisstofninn.</li><li>\(dx\) segir að heildað sé með tilliti til \(x\).</li><li>\(F(x)+C\) lýsir fjölskyldu stofnfalla.</li></ul><h3>Leyst dæmi</h3>\[\int 6x\,dx=3x^2+C.\]<p>Svarið er fjölskylda falla, ekki ein tala. Við athugum með því að diffra hægri hliðina.</p><aside>Þegar beðið er um óákveðið heildi tökum við heildunarfastann \(C\) með. Þegar beðið er um eitt stofnfall nægir eitt val, til dæmis \(C=0\).</aside><p>Heildunarbreytan getur heitið annað: \(\int 2t\,dt=t^2+C\).</p>''',[
(r'Reiknaðu \(\int 7\,dx\).','Hvaða fall hefur fasta afleiðu 7?',r'Afleiða \(7x\) er \(7\).',r'\(7x+C\).'),
(r'Reiknaðu \(\int 2t\,dt\).','Heildunarbreytan er t.',r'Afleiða \(t^2\) með tilliti til t er \(2t\).',r'\(t^2+C\).')]),
('Veldisreglan','Heilda veldi og endurrita rætur og brot.',r'''<p>Diffrun lækkar veldisvísi um einn. Við heildun hækkum við hann um einn og deilum með nýja veldisvísinum:</p>\[\int x^n\,dx=\frac{x^{n+1}}{n+1}+C,\qquad n\ne-1.\]<p>Reglan gildir á bilum þar sem föllin eru skilgreind.</p><h3>Leyst dæmi</h3>\[\int x^3\,dx=\frac{x^4}{4}+C.\]\[\int \sqrt{x}\,dx=\int x^{1/2}\,dx=\frac{x^{3/2}}{3/2}+C=\frac23x^{3/2}+C.\]\[\int \frac1{x^2}\,dx=\int x^{-2}\,dx=\frac{x^{-1}}{-1}+C=-\frac1x+C.\]<p>Síðasta dæmið er skoðað á bili sem inniheldur ekki núll.</p><aside>Undantekningin \(n=-1\) er mikilvæg: deiling með \(n+1\) væri deiling með núlli. Stofnfall \(1/x\) kemur á síðu 1.6.</aside>''',[
(r'Reiknaðu \(\int x^5\,dx\).','Hækkaðu veldisvísinn um einn.',r'Nýi veldisvísirinn er 6. Deildu með 6.',r'\(x^6/6+C\).'),
(r'Reiknaðu \(\int x^{-3}\,dx\).','Reglan gildir líka fyrir neikvæð veldi önnur en −1.',r'\(-3+1=-2\).',r'\(-\tfrac12x^{-2}+C=-1/(2x^2)+C\), á bili sem inniheldur ekki 0.'),
(r'Reiknaðu \(\int \sqrt[3]{x}\,dx\).','Skrifaðu rótina sem veldi.',r'\(\sqrt[3]{x}=x^{1/3}\) og \(1/3+1=4/3\).',r'\(\tfrac34x^{4/3}+C\).')]),
('Summur og fastir stuðlar','Heilda lið fyrir lið og halda utan um stuðla.',r'''<p>Við getum heildað summu lið fyrir lið og dregið fasta stuðla út fyrir heildi:</p>\[\int(af(x)+bg(x))\,dx=a\int f(x)\,dx+b\int g(x)\,dx.\]<p>Hér eru \(a\) og \(b\) fastar. Í lokasvari sameinum við alla heildunarfasta í einn fasta \(C\).</p><h3>Leyst dæmi</h3>\[\begin{aligned}\int(3x^2-4x+2)\,dx&=3\frac{x^3}{3}-4\frac{x^2}{2}+2x+C\\&=x^3-2x^2+2x+C.\end{aligned}\]<p>Athugun: \((x^3-2x^2+2x+C)'=3x^2-4x+2\).</p><h3>Einföldum fyrst</h3><p>Til dæmis er \((x^2+2x)/x=x+2\) þegar \(x\ne0\). Þá má heilda lið fyrir lið á bili sem inniheldur ekki núll.</p><aside>Ekki má almennt heilda margfeldi með því að margfalda stofnföll. Seinna lærum við aðferðir fyrir margfeldi og samsett föll.</aside>''',[
(r'Reiknaðu \(\int(4x^3-6x+5)\,dx\).','Heilda má hvern lið fyrir sig.',r'\(4x^4/4-6x^2/2+5x\), og síðan fastinn.',r'\(x^4-3x^2+5x+C\).'),
(r'Reiknaðu \(\int(2\sqrt{x}+3/x^2)\,dx\), fyrir \(x>0\).','Endurritaðu sem veldi.',r'Heilda \(2x^{1/2}+3x^{-2}\).',r'\(\tfrac43x^{3/2}-3/x+C\).')]),
('Önnur grunnstofnföll','Nota grunnreglur fyrir vísis-, logra- og hornaföll.',r'''<p>Þessar reglur byggjast allar á diffrun sem þú þekkir:</p><div class="formula">\[\begin{aligned}\int e^x\,dx&=e^x+C\\\int a^x\,dx&=\frac{a^x}{\ln a}+C\quad(a>0,\ a\ne1)\\\int\sin x\,dx&=-\cos x+C\\\int\cos x\,dx&=\sin x+C\\\int\frac1x\,dx&=\ln|x|+C\quad(x\ne0).\end{aligned}\]</div><p>Reglan fyrir \(1/x\) er notuð á bili sem inniheldur ekki núll. Fyrir jákvætt \(x\) er \(\ln|x|=\ln x\); fyrir neikvætt \(x\) er \(\ln|x|=\ln(-x)\).</p><h3>Leyst dæmi</h3>\[\int(2e^x-3\sin x+4/x)\,dx=2e^x+3\cos x+4\ln|x|+C.\]<p>Plusmerkið fyrir framan \(3\cos x\) er rétt: afleiða þess er \(-3\sin x\).</p><p>Við höldum okkur hér við grunnföll. Föll eins og \(e^{2x}\) og \(\sin(3x)\) fá sérstaka umfjöllun með innsetningu.</p>''',[
(r'Reiknaðu \(\int(3e^x+2\cos x)\,dx\).','Heilda lið fyrir lið og halda stuðlunum.',r'Stofnföll grunnfallanna eru \(e^x\) og \(\sin x\).',r'\(3e^x+2\sin x+C\).'),
(r'Reiknaðu \(\int(2/x-\sin x)\,dx\).','Gættu að algildismerki og formerki.',r'Afleiða \(\cos x\) er \(-\sin x\).',r'\(2\ln|x|+\cos x+C\), á bili sem inniheldur ekki 0.'),
(r'Reiknaðu \(\int 2^x\,dx\).','Afleiða \(2^x\) er \((\ln2)2^x\).',r'Deiling með \(\ln2\) leiðréttir stuðulinn.',r'\(2^x/\ln2+C\).')]),
('Upphafsskilyrði velja stofnfall','Finna fastann og athuga bæði afleiðu og skilyrði.',r'''<p>Þegar punktur á grafinu er gefinn getum við valið tiltekið stofnfall úr fjölskyldunni.</p><h3>Leyst dæmi</h3><p>Finnum \(F\) þannig að \(F'(x)=2x\) og \(F(1)=4\).</p><ol><li>Heildum: \(F(x)=x^2+C\).</li><li>Setjum skilyrðið inn: \(4=1^2+C\), svo \(C=3\).</li><li>Svarið er \(F(x)=x^2+3\).</li></ol><p>Við athugum tvennt: \(F'(x)=2x\) og \(F(1)=1+3=4\). Bæði þurfa að standast.</p><aside>Táknmálið \(y'=2x\), \(y(1)=4\) lýsir sama verkefni. Þetta er einfalt dæmi um deildajöfnu með upphafsskilyrði.</aside><p>Í grafverkfærinu á síðu 1.2 má velja \(C=3\) og athuga að grafið fari í gegnum punktinn \((1,4)\).</p>''',[
(r'Finndu \(F\) ef \(F\prime(x)=3x^2-4\) og \(F(1)=2\).','Finndu fyrst fjölskyldu stofnfalla.',r'\(F(x)=x^3-4x+C\). Settu síðan x=1 og F(1)=2.',r'\(2=1-4+C\), svo \(C=5\). Svar: \(F(x)=x^3-4x+5\). Afleiðan og skilyrðið standast.'),
(r'Finndu \(y\) ef \(y\prime=2e^x\) og \(y(0)=5\).','Stofnfall e í x er e í x.',r'\(y=2e^x+C\) og \(e^0=1\).',r'\(5=2+C\), svo \(y=2e^x+3\). Athugun: y(0)=5 og afleiðan er \(2e^x\).')]),
('Samantekt og sjálfsprófun','Velja reglu, reikna og athuga eigið svar.',r'''<p>Þú hefur nú lært að finna stofnföll með grunnreglum. Áður en þú heldur áfram skaltu prófa verkefnin án þess að opna stuðninginn.</p><aside><strong>Vinnuleið:</strong> 1. Skoða og einfalda. 2. Velja grunnreglu. 3. Heilda og bæta við C. 4. Sannreyna með diffrun. 5. Nota og athuga upphafsskilyrði ef þau eru gefin.</aside><p>Vísbendingar eru hluti af æfingunni. Ef þú þarft þær skaltu reyna sambærilegt dæmi síðar án stuðnings. Hér er ekki sjálfvirk einkunnagjöf; berðu eigin úrlausn saman við skýringuna.</p>''',[
(r'Reiknaðu \(\int(6x^2-4x+3)\,dx\).','Heilda lið fyrir lið.',r'Hækkaðu veldi um einn og deildu með nýja veldinu.',r'\(2x^3-2x^2+3x+C\). Ef stuðlar valda erfiðleikum skaltu rifja upp 1.4–1.5.'),
(r'Reiknaðu \(\int(1/\sqrt{x}+e^x)\,dx\), fyrir \(x>0\).','Skrifaðu fyrri liðinn sem veldi.',r'\(1/\sqrt{x}=x^{-1/2}\). Nýja veldið er 1/2.',r'\(2\sqrt{x}+e^x+C\). Rifjaðu upp 1.4 og 1.6 eftir þörfum.'),
(r'Reiknaðu \(\int(3/x+2\sin x)\,dx\).','Annar liðurinn krefst þess að gæta að mínusmerki.',r'\(\int\sin x\,dx=-\cos x+C\).',r'\(3\ln|x|-2\cos x+C\), á bili sem inniheldur ekki 0. Rifjaðu upp 1.6 eftir þörfum.'),
(r'Finndu \(F\) ef \(F\prime(x)=4x\) og \(F(2)=3\).','Finndu fyrst almenna stofnfallið.',r'\(F(x)=2x^2+C\). Notaðu punktinn (2,3).',r'\(C=-5\), svo \(F(x)=2x^2-5\). Athugaðu afleiðuna og F(2). Sjá 1.7.'),
(r'Útskýrðu hvers vegna \(\int x^{-1}\,dx=x^0/0+C\) er rangt.','Hvaða skilyrði fylgir veldisreglunni?',r'Veldisreglan gildir aðeins þegar n er ekki −1.',r'Deiling með núlli er óskilgreind. Rétt svar er \(\ln|x|+C\) á viðeigandi bili. Sjá 1.4 og 1.6.')])]

